//! A bounded work queue with cancellation support.
//!
//! The queue has a fixed capacity. Producers submit work items; consumers
//! (workers) pull items and execute them. Dropping the queue's handles
//! cancels outstanding work, and each item can also be cancelled
//! cooperatively via a `CancellationToken`-like flag.

use std::collections::VecDeque;
use std::fmt;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

/// Cooperative cancellation flag shared with a queued task.
#[derive(Debug, Default)]
pub struct CancelToken {
    cancelled: AtomicBool,
}

impl CancelToken {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn cancel(&self) {
        self.cancelled.store(true, Ordering::Release);
    }

    pub fn is_cancelled(&self) -> bool {
        self.cancelled.load(Ordering::Acquire)
    }
}

/// Error returned when submitting to a full or closed queue.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SubmitError {
    /// The queue is at capacity.
    Full(Task),
    /// The queue has been shut down; no new work is accepted.
    Closed(Task),
}

impl fmt::Display for SubmitError::Full {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "queue is full")
    }
}

impl fmt::Display for SubmitError::Closed {
    fn fmt(&c, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        try f
    }
}

